const icons={pen:'<path d="m15 5 4 4M4 20l4-1L20 7a2.8 2.8 0 0 0-4-4L4 15z"/><path d="m4 15 5 5"/>',arrow:'<path d="M4 12h15m-5-5 5 5-5 5"/>',file:'<path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9z"/><path d="M14 3v6h6M8 13h8m-8 4h5"/>',book:'<path d="M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1zm0 0v15"/><path d="M5 8h3m-3 4h3m8-4h3m-3 4h3"/>',search:'<circle cx="10" cy="10" r="6.5"/><path d="m15 15 5 5"/>',crown:'<path d="m3 6 4 4 5-6 5 6 4-4-3 13H6zM7 22h10"/>',play:'<path d="m8 4 12 8-12 8z"/>',scan:'<path d="M8 3H5a2 2 0 0 0-2 2v3m13-5h3a2 2 0 0 1 2 2v3M3 16v3a2 2 0 0 0 2 2h3m8 0h3a2 2 0 0 0 2-2v-3"/><circle cx="11" cy="11" r="4"/><path d="m14 14 3 3"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',edit:'<path d="M12 4H5v16h15v-8M16 3l5 5-9 9H7v-5z"/><path d="m13 6 5 5"/>',presentation:'<path d="M3 3h18v13H3zM12 16v5m-5 0 5-5 5 5M7 12l3-3 3 2 4-5"/>',chart:'<path d="M4 3v18h17M8 16v-4m5 4V6m5 10V9"/><circle cx="8" cy="8" r="1"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 14v6h16v-6"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 16v5h16v-5"/>',sparkles:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5zM20 2v4m-2-2h4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',cap:'<path d="m2 9 10-6 10 6-10 6zM6 12v6c4 3 8 3 12 0v-6M22 9v8"/>',send:'<path d="m21 3-7 19-4-9-8-4zM10 13 21 3"/>'};
const svg=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.file}</svg>`;
function hydrate(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=svg(el.dataset.icon));}
const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let degree='本科论文';let previewTab='outline';let currentTitle='基于大语言模型的智能教育系统研究';let generated=false;let storedOutline='';
const tools={check:{name:'论文查重',icon:'scan',desc:'相似度检测与报告'},aigc:{name:'AI 率检测',icon:'shield',desc:'文本特征分析'},rewrite:{name:'降重复率',icon:'edit',desc:'学术表达与段落优化'},reduce:{name:'降 AI 率',icon:'sparkles',desc:'保留观点，优化表达'},format:{name:'格式排版',icon:'file',desc:'论文格式与引用规范'},ppt:{name:'PPT创作',icon:'presentation',desc:'开题与答辩演示'},research:{name:'科研工具',icon:'chart',desc:'数据分析与科研绘图'},reading:{name:'AI研读',icon:'book',desc:'阅读、综述与研究空白'},review:{name:'导师批注修改',icon:'edit',desc:'拆解意见与修改建议'},journal:{name:'期刊投稿',icon:'send',desc:'选刊与投稿准备'},resume:{name:'简历创作',icon:'file',desc:'学术经历与求职简历'}};
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),3200);}
function readStore(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
function writeStore(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{toast('浏览器无法保存，请导出到本地留存');return false;}}
function outlineHtml(title=currentTitle){const chapters=[['绪论',['研究背景与问题提出','研究目的与研究意义','研究内容、方法与技术路线']],['理论基础与文献综述',['核心概念与理论基础','国内外研究现状','现有研究评述与研究切入点']],['研究设计与方法',['研究框架与研究假设','数据来源与样本选择','变量定义与分析方法']],['研究结果与讨论',['研究结果呈现','结果分析与比较','理论与实践启示']],['结论与展望',['研究结论','研究局限','未来研究方向']]];return `<h3>${esc(title)}</h3><p class="doc-subtitle">（${esc(degree)} · ${generated?'可编辑的大纲模板':'结构示例'}）</p>`+chapters.map(([t,items],i)=>`<div class="outline-chapter"><h4>第${i+1}章　${t}</h4>${items.map((t,j)=>`<p>${i+1}.${j+1}　${t}</p>`).join('')}</div>`).join('');}
function renderPreview(){const el=$('#document-preview');el.contentEditable=generated&&previewTab==='outline'?'true':'false';el.setAttribute('aria-label',generated?'编辑论文大纲':'论文内容示例');if(previewTab==='outline'){el.innerHTML=storedOutline||outlineHtml();}else if(previewTab==='paragraph'){el.innerHTML=`<h3>${esc(currentTitle)}</h3><p class="doc-subtitle">论文片段 · 写作结构示例</p><h4>1.1 研究背景</h4><p>围绕“${esc(currentTitle)}”，研究首先需要界定核心概念、明确讨论边界，并说明这一问题在相关学科中的位置。</p><p style="margin-top:16px">在撰写研究背景时，可以从现实情境出发，梳理已有研究已经回答了哪些问题，以及哪些方面仍有待进一步验证。随后，将具体研究问题与研究目标对应起来。</p><p style="margin-top:16px;color:#7894bd">此段为结构模板示例，需结合真实资料、数据与研究结果自行完善。</p>`;}else{el.innerHTML='<h3>建立你的参考文献清单</h3><p class="doc-subtitle">规范引用，从真实来源开始</p><h4>建议准备的文献</h4><p>01　与你的研究问题直接相关的基础文献</p><p>02　近三至五年的同领域研究</p><p>03　研究方法与数据来源说明</p><h4>参考格式示例</h4><p>作者. 文章标题[J]. 期刊名称, 年份, 卷(期): 页码.</p><p style="margin-top:20px;color:#7894bd">本地体验版未连接文献数据库，不生成虚构的引用条目。你可以在正式版本中添加并核验真实文献。</p>';}}
function saveCurrent(){if(!generated)return;const drafts=readStore('paperknow-drafts',[]);const item={id:currentDraftId||Date.now(),title:currentTitle,degree,major:$('#major').value,html:storedOutline||outlineHtml(),date:new Date().toLocaleString('zh-CN')};currentDraftId=item.id;const index=drafts.findIndex(d=>d.id===item.id);if(index>=0)drafts[index]=item;else drafts.unshift(item);writeStore('paperknow-drafts',drafts.slice(0,30));}
let currentDraftId=null;
function bindDegree(){document.querySelectorAll('[data-degree]').forEach(b=>b.addEventListener('click',()=>{degree=b.dataset.degree;document.querySelectorAll('[data-degree]').forEach(x=>x.classList.toggle('selected',x===b));}));}
function fileSelected(file,label){if(!file)return false;if(!/\.(docx?|pdf|txt)$/i.test(file.name)){toast('请选择 DOC、DOCX、PDF 或 TXT 文件');return false;}if(file.size>50*1024*1024){toast('文件不能超过 50MB');return false;}label.textContent=file.name+' · 已选择（不上传）';return true;}
function setupDrop(zone,input,label){input.addEventListener('change',()=>{if(!fileSelected(input.files[0],label))input.value='';});zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('dragging');});zone.addEventListener('dragleave',()=>zone.classList.remove('dragging'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragging');const file=e.dataTransfer.files[0];if(fileSelected(file,label)){const transfer=new DataTransfer();transfer.items.add(file);input.files=transfer.files;}});}
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name.replace(/[\\/:*?"<>|]/g,'_');a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function renderLiterature(mode='search'){const texts={search:[['Artificial intelligence in education: a systematic review','示例条目 · 教育技术 · 文献检索预览'],['Personalized learning with large language models','示例条目 · 个性化学习 · 文献检索预览'],['Ethics and challenges of AI in education','示例条目 · 教育伦理 · 文献检索预览']],read:[['抓住核心问题','提取研究目标、方法与关键发现'],['对照研究证据','定位论点对应的数据和实验'],['记录你的思考','把阅读笔记转化为研究线索']],summary:[['按研究主题归类','整理不同研究之间的联系'],['对比研究方法与结论','找出共识、差异与争议'],['形成综述结构','从文献清单走向有逻辑的叙述']],gap:[['研究对象是否充分覆盖？','检查样本范围与代表性'],['已有方法是否存在局限？','比较不同方法的适用条件'],['哪些结果仍需要验证？','识别尚未充分回答的问题']]};$('#literature-results').innerHTML=texts[mode].map(([t,d])=>`<button class="literature-item" data-tool="reading"><span><b>${t}</b><small>${d}</small></span><span>查看 ›</span></button>`).join('');}
function renderLower(){const steps=[['选题','明确研究方向','pen','topic'],['开题','建立研究框架','file','proposal'],['文献','检索 · 阅读 · 综述','book','reading'],['写作','构建论文初稿','pen','writing'],['修改','优化内容与表达','edit','review'],['格式','规范排版与引用','scan','format'],['答辩','梳理展示与讲述','send','ppt'],['投稿','准备材料与选刊','shield','journal']];$('#workflow').innerHTML=steps.map(([name,desc,icon,tool],i)=>`<button class="workflow-item" data-tool="${tool}"><span class="workflow-icon">${svg(icon)}</span><strong><small>0${i+1}</small>${name}</strong><small>${desc}</small></button>`).join('');const audiences=[['专科','毕业设计 / 任务书','开题报告 / 答辩','专科论文'],['本科','选题 / 开题 / 中期','毕业论文 / 查重','本科论文'],['硕士','文献综述 / 数据分析','学位论文 / 期刊投稿','硕士论文'],['博士','研究设计 / 学术写作','SCI 发表 / 外审回复','博士论文'],['科研人员','文献管理 / 研究分析','期刊匹配 / 学术翻译','期刊论文']];$('#audience-grid').innerHTML=audiences.map(([a,b,c,d])=>`<button class="audience-card" data-audience="${d}"><span>${svg(a==='科研人员'?'shield':'cap')}</span><div><b>${a}</b><p>${b}<br>${c}</p><em>立即使用 ›</em></div></button>`).join('');}
const dialog=$('#tool-dialog');let activeTool='';
function showDialog(title,html){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;hydrate(dialog);if(!dialog.open)dialog.showModal();document.body.style.overflow='hidden';}
function closeDialog(){dialog.close();document.body.style.overflow='';}
const notice='<div class="demo-notice">本地体验模式 · 仅展示操作流程与示例，暂未连接 AI、检测数据库或在线服务。</div>';
const uploadMarkup='<label class="upload-zone modal-upload" id="modal-drop"><input id="modal-file" type="file" accept=".doc,.docx,.txt,.pdf"><span class="upload-icon" data-icon="upload"></span><span id="modal-file-label">选择或拖拽你的文档</span><small>DOC / DOCX / PDF / TXT · 最大 50MB · 仅本地选择</small></label>';
const emptyOutput='<div class="empty-result">'+svg('file')+'<span>你的工作成果将在这里呈现</span><small>先填写左侧内容，体验操作流程</small></div>';
function toolCards(filter=''){const entries=Object.entries(tools).filter(([,t])=>(t.name+t.desc).toLowerCase().includes(filter.toLowerCase()));return entries.length?entries.map(([key,t])=>`<button class="tool-search-card" data-tool="${key}">${svg(t.icon)}<span><b>${t.name}</b><small>${t.desc}</small></span></button>`).join(''):'<p class="muted">没有匹配的工具，试试“论文”“查重”或“文献”。</p>';}
function openTool(key){if(key==='check'){location.assign('/precheck/');return;}activeTool=key;$('#more-menu').hidden=true;$('#more-button').setAttribute('aria-expanded','false');$('nav').classList.remove('mobile-open');
if(key==='writing'){closeDialog();$('#writing').scrollIntoView();$('#paper-title').focus({preventScroll:true});return;}
if(key==='search'){showDialog('找到你的科研工具',`<input id="tool-search-input" placeholder="搜索工具，例如：查重、文献、PPT" aria-label="搜索工具名称"><div class="tool-search-grid" id="tool-search-results">${toolCards()}</div>`);$('#tool-search-input').addEventListener('input',e=>$('#tool-search-results').innerHTML=toolCards(e.target.value));return;}
if(key==='intro'){showDialog('从一个题目，到一篇清晰的论文',`<p class="workspace-intro">PaperKnow 让研究中的每一个阶段都有对应的工具。</p><div class="step-list">${[['确定研究方向','从选题与开题开始，明确你的问题、目标与研究方法。'],['建立文献基础','阅读相关工作，整理证据，找到值得继续探索的空间。'],['写作与修改','搭建大纲，完善论证，逐条回应导师的修改意见。'],['完成与分享','规范格式，检查文本，准备答辩与投稿材料。']].map(([t,d],i)=>`<div><b class="step-number">${i+1}</b><div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}</div><div class="workspace-actions"><button class="button" data-tool="writing">从论文大纲开始</button></div>`);return;}
if(key==='member'){showDialog('为你的研究，选择合适的支持',`${notice}<div class="member-grid">${[['基础体验','免费体验','论文大纲模板|本地草稿保存|大纲文本导出'],['学术进阶','即将开放','完整写作工作流|文献研读辅助|论文修改与排版'],['科研专业','即将开放','深入研究辅助|数据分析与绘图|多项目管理']].map(([t,p,f],i)=>`<div class="member-card ${i===1?'featured':''}"><h3>${t}</h3><strong>${p}</strong><ul>${f.split('|').map(x=>`<li>${x}</li>`).join('')}</ul><button class="button full ${i?'soft':''}" ${i?'data-unavailable="会员服务与价格尚未开放，当前不会产生扣费"':'data-tool="writing"'}>${i?'了解开放状态':'开始体验'}</button></div>`).join('')}</div>`);return;}
if(key==='login'){const user=readStore('paperknow-local-profile',null);showDialog(user?'我的体验空间':'欢迎来到 PaperKnow',`<div class="modal-form"><p class="workspace-intro">使用昵称进入本地体验，不需要真实账号或密码。</p><form id="local-login"><label for="nickname">你的昵称</label><input id="nickname" maxlength="20" placeholder="例如：正在写论文的小林" value="${esc(user?.name||'')}" required><button class="button full" type="submit">${user?'保存昵称':'进入本地体验'}</button></form><p>此昵称只保存在当前浏览器。正式登录服务将在后续接入。</p>${user?'<button class="text-button" id="logout">退出本地体验</button>':''}</div>`);$('#local-login').addEventListener('submit',e=>{e.preventDefault();const name=$('#nickname').value.trim();if(!name)return;writeStore('paperknow-local-profile',{name});$('#account-button').textContent=name.slice(0,6);closeDialog();toast('欢迎，'+name);});$('#logout')?.addEventListener('click',()=>{localStorage.removeItem('paperknow-local-profile');$('#account-button').textContent='登录';closeDialog();toast('已退出本地体验');});return;}
if(key==='history'){renderHistory();return;}
if(key==='feedback'){showDialog('让 PaperKnow 更贴近你的研究',`<p class="workspace-intro">记录你的建议，下载后可发给开发者。当前不会在线发送。</p><form id="feedback-form"><textarea id="feedback-text" rows="5" required placeholder="你希望改进哪些地方？"></textarea><div class="workspace-actions"><button class="button" type="submit">下载反馈</button></div></form>`);$('#feedback-form').addEventListener('submit',e=>{e.preventDefault();download('PaperKnow-反馈.txt',$('#feedback-text').value);toast('反馈已导出');});return;}
if(key==='topic'||key==='proposal'){showDialog(key==='topic'?'智能选题':'开题报告',`${notice}<p class="workspace-intro">${key==='topic'?'输入研究方向，查看选题组织方式。':'输入论文题目，梳理开题报告结构。'}</p><form id="topic-form"><input id="topic-input" aria-label="研究方向或题目" placeholder="例如：人工智能与教育" required minlength="2" maxlength="100"><div class="workspace-actions"><button class="button" type="submit">${key==='topic'?'查看选题模板':'生成开题框架'}</button></div></form><div id="topic-result" style="margin-top:20px"></div>`);$('#topic-form').addEventListener('submit',e=>{e.preventDefault();const t=$('#topic-input').value.trim();$('#topic-result').innerHTML=key==='topic'?`<div class="step-list">${[`${t}的应用现状与发展路径研究`,`${t}的影响因素及作用机制研究`,`${t}的实践困境与优化策略研究`].map(t=>`<div><p>${esc(t)}</p><button class="text-button" data-use-topic="${esc(t)}">使用选题</button></div>`).join('')}</div>`:`<div class="workspace-output"><h3>${esc(t)}</h3>一、选题背景与研究意义\n二、国内外研究现状\n三、研究目标与核心问题\n四、研究方法与技术路线\n五、研究计划与预期成果\n六、参考文献（待添加核验）</div>`;});return;}
if(key==='research'){showDialog('科研绘图',`<p class="workspace-intro">把数据变成更容易理解的图表。支持本地生成柱状图。</p><div class="workspace-grid"><form id="chart-form"><label for="chart-title">图表标题</label><input id="chart-title" value="不同教学方法的学习效果" maxlength="60"><label for="chart-data" style="margin-top:16px">数据（每行：名称,数值）</label><textarea id="chart-data" required>传统课堂,65\n混合学习,78\n个性化学习,91\n自主学习,73</textarea><button class="button full" type="submit" style="margin-top:12px">生成柱状图</button><p class="modal-error" id="chart-error" role="alert"></p></form><div><div class="workspace-output" id="chart-result">${emptyOutput}</div><button class="text-button" id="chart-export" hidden style="margin-top:12px">下载图表 SVG</button></div></div>`);let chartSvg='';$('#chart-form').addEventListener('submit',e=>{e.preventDefault();const rows=$('#chart-data').value.trim().split('\n').map(l=>l.split(/[,，]/).map(v=>v.trim()));if(rows.length>8||rows.some(r=>r.length!==2||!r[0]||r[1]===''||!Number.isFinite(Number(r[1]))||Number(r[1])<0)){ $('#chart-error').textContent='请输入最多 8 组有效数据，数值须为非负数字。';return;}$('#chart-error').textContent='';const max=Math.max(1,...rows.map(r=>Number(r[1])));const title=$('#chart-title').value;$('#chart-result').innerHTML=`<h3>${esc(title)}</h3><div class="chart-preview">${rows.map(([n,v])=>`<div class="chart-column" style="--height:${Number(v)/max*80}%"><b>${esc(v)}</b><span>${esc(n)}</span></div>`).join('')}</div><small>根据当前输入数据生成</small>`;chartSvg=`<svg xmlns="http://www.w3.org/2000/svg" width="800" height="480" viewBox="0 0 800 480"><rect width="800" height="480" fill="white"/><text x="40" y="45" font-family="sans-serif" font-size="24" fill="#183052">${esc(title)}</text>${rows.map(([n,v],i)=>{const x=55+i*(690/rows.length),h=Number(v)/max*280;return `<rect x="${x}" y="${370-h}" width="${Math.min(65,500/rows.length)}" height="${h}" rx="4" fill="#2e78ff"/><text x="${x}" y="${355-h}" font-size="15" font-family="sans-serif" fill="#345">${esc(v)}</text><text x="${x}" y="405" font-size="14" font-family="sans-serif" fill="#789">${esc(n)}</text>`}).join('')}</svg>`;$('#chart-export').hidden=false;});$('#chart-export').addEventListener('click',()=>download('PaperKnow-科研图表.svg',chartSvg));return;}
const conf={check:['论文相似度检测','上传论文或粘贴文本，预览检测提交流程。','粘贴需要检测的论文内容…','专业版|旗舰版|AI 率检测','查看检测示例'],aigc:['AI 率检测','了解文本分析流程与报告结构。','粘贴需要检测的文本…','中文检测|英文检测','查看报告结构'],rewrite:['论文降重与润色','保留核心论点，优化表达方式与段落逻辑。','粘贴需要优化的段落…','标准润色|深度改写|学术表达','查看修改流程'],reduce:['表达优化','明确论点，补充证据，让表达更自然。','粘贴需要优化的内容…','保留结构|逻辑优化','查看优化流程'],format:['论文格式排版','选择排版要求，上传文档，预览标准结构。','在这里补充学校的格式要求…','通用本科模板|通用硕士模板|自定义要求','预览格式结构'],ppt:['开题与答辩 PPT','用清晰的故事线，讲明白你的研究。','输入你的论文题目或研究内容…','毕业答辩|开题汇报|课程展示','生成演示提纲'],reading:['AI 文献研读','带着问题阅读，整理方法、证据与结论。','粘贴一段文献摘要…','研究摘要|阅读笔记|研究空白','生成阅读框架'],review:['导师批注修改','把导师的意见拆解成可以逐项完成的修改任务。','粘贴导师的具体修改意见…','内容问题|表达问题|格式问题','整理修改清单'],journal:['期刊投稿助手','梳理投稿材料与选刊条件。','输入论文题目和研究领域…','中文期刊|英文期刊','生成投稿清单'],resume:['学术简历','清晰呈现你的教育背景和研究经历。','输入你的姓名、教育背景与研究经历…','学术申请|实习求职','生成简历框架']}[key];
if(!conf)return;const [title,desc,placeholder,options,action]=conf;showDialog(title,`${notice}<p class="workspace-intro">${desc}</p><div class="segmented">${options.split('|').map((x,i)=>`<button class="${i?'':'selected'}" data-option>${x}</button>`).join('')}</div><div class="workspace-grid"><form id="workspace-form">${['check','aigc','format','reading','review'].includes(key)?uploadMarkup:''}<label for="workspace-text">${key==='format'?'补充要求（可选）':'输入内容'}</label><textarea id="workspace-text" placeholder="${placeholder}" maxlength="20000"></textarea><button class="button full" type="submit" style="margin-top:12px">${action}</button><p class="modal-error" id="workspace-error" role="alert"></p></form><div><div class="workspace-output" id="workspace-output">${emptyOutput}</div><button class="text-button" id="export-result" hidden style="margin-top:10px">下载当前结果</button></div></div>`);if($('#modal-file'))setupDrop($('#modal-drop'),$('#modal-file'),$('#modal-file-label'));dialog.querySelectorAll('[data-option]').forEach(b=>b.addEventListener('click',()=>{dialog.querySelectorAll('[data-option]').forEach(x=>x.classList.toggle('selected',x===b));$('#workspace-output').innerHTML=emptyOutput;$('#export-result').hidden=true;}));$('#workspace-form').addEventListener('submit',e=>{e.preventDefault();const text=$('#workspace-text').value.trim();const file=$('#modal-file')?.files[0];if(!text&&!file){$('#workspace-error').textContent='请先输入内容或选择文档。';return;}$('#workspace-error').textContent='';const mode=dialog.querySelector('[data-option].selected').textContent;let result='';const subject=text.slice(0,100)||file.name;if(['check','aigc'].includes(key)){result=`${mode} · 报告结构预览\n\n提交内容：${file?file.name:text.length+' 字文本'}\n\n检测状态：未执行\n${key==='aigc'?'AIGC 特征分析':'相似度结果'}：待接入检测服务\n相似片段与来源：待接入检测服务\n详细报告：待接入检测服务\n\n当前没有实际比对数据库，因此不展示检测百分比。`;}else if(['rewrite','reduce'].includes(key)){result=`${mode} · 修改工作流\n\n原文（节选）：\n${text.slice(0,350)}\n\n建议的修改顺序\n1. 保留段落的核心论点与来源引用。\n2. 检查重复表述与不必要的套话。\n3. 补充具体证据，明确因果或比较关系。\n4. 调整句子结构，并逐句核对原意。\n\n当前尚未执行 AI 改写；这里展示的是操作建议。`;}else if(key==='ppt'){result=`${subject}\n${mode} · 模板提纲\n\n01　封面：题目、姓名与所属院系\n02　研究背景：问题从何而来\n03　文献回顾：已有研究与不足\n04　研究目标：本研究回答什么\n05　研究方法：数据与研究设计\n06　研究结果：关键证据与发现（待填写）\n07　结论：贡献、局限与未来方向\n08　致谢与问答\n\n此为演示提纲，可导出文本；PPTX 生成将在后续接入。`;}else if(key==='format'){result=`${mode} · 排版结构示例\n\n封面\n中文摘要与关键词\n英文摘要与关键词\n目录\n1 绪论\n2 文献综述\n3 研究方法\n4 研究结果与讨论\n5 结论\n参考文献\n附录与致谢\n\n补充要求：${text||'未填写'}\n\n请以学校发布的最新规范为准。当前未读取或修改上传文档。`;}else if(key==='reading'){result=`${mode} · 阅读记录模板\n\n材料：${subject}\n\n研究问题：作者试图解决什么问题？\n研究方法：采用了什么数据与方法？\n主要发现：最关键的结果是什么？\n证据与局限：结论适用于哪些条件？\n我的思考：与当前研究有哪些联系？\n\n这是用于填写的阅读框架，尚未执行 AI 文献分析。`;}else if(key==='review'){result=`${mode} · 修改清单模板\n\n导师意见：${subject}\n\n□ 定位对应的章节与段落\n□ 明确导师希望解决的具体问题\n□ 补充论据或重组段落结构\n□ 检查引用与格式是否一致\n□ 记录修改位置与修改说明\n\n此为通用任务模板，尚未解析文件批注或执行 AI 修改。`;}else if(key==='journal'){result=`${mode} · 投稿准备清单\n\n研究主题：${subject}\n\n□ 确认目标期刊的征稿范围\n□ 核对文章类型、语言与篇幅\n□ 阅读目标期刊近期相关文章\n□ 准备正文、图表及数据说明\n□ 准备投稿信与作者贡献声明\n□ 核对伦理、利益冲突与版权要求\n\n当前未连接期刊数据库，不提供匹配结果或投稿保证。`;}else{result=`${mode} · 简历框架\n\n个人资料：${subject}\n\n一、教育背景\n二、研究方向与项目经历\n三、论文、报告与作品\n四、专业技能\n五、获奖与其他经历\n\n请补充可核实的真实经历。当前为结构模板。`;}
$('#workspace-output').textContent=result;$('#export-result').hidden=false;});$('#export-result').addEventListener('click',()=>download(`PaperKnow-${title}.txt`,$('#workspace-output').innerText));}
function renderHistory(){const drafts=readStore('paperknow-drafts',[]);showDialog('我的创作',`<p class="workspace-intro">保存在当前浏览器中的论文大纲。</p>${drafts.length?drafts.map(d=>`<div class="history-item"><div><b>${esc(d.title)}</b><p>${esc(d.degree)} · ${esc(d.date)}</p></div><div><button class="button small soft" data-load="${d.id}">继续编辑</button> <button class="text-button" data-delete="${d.id}">删除</button></div></div>`).join(''):'<div class="empty-result">'+svg('file')+'<p>还没有创作记录</p><button class="button" data-tool="writing">开始第一篇论文</button></div>'}`);}
function restoreDraft(d){currentTitle=d.title;degree=d.degree;currentDraftId=d.id;storedOutline=d.html;generated=true;$('#paper-title').value=d.title;$('#major').value=d.major;$('#paper-title').dispatchEvent(new Event('input'));document.querySelectorAll('[data-degree]').forEach(b=>b.classList.toggle('selected',b.dataset.degree===degree));previewTab='outline';document.querySelectorAll('[data-preview]').forEach(b=>{b.classList.toggle('selected',b.dataset.preview==='outline');b.setAttribute('aria-selected',b.dataset.preview==='outline'?'true':'false');});renderPreview();$('#preview-label').textContent='我的论文大纲 · 点击编辑';ensureSaveButton();closeDialog();$('#writing').scrollIntoView();}
function setPreview(tab){if(previewTab==='outline'&&generated)storedOutline=$('#document-preview').innerHTML;previewTab=tab;document.querySelectorAll('[data-preview]').forEach(b=>{b.classList.toggle('selected',b.dataset.preview===tab);b.setAttribute('aria-selected',b.dataset.preview===tab?'true':'false');});renderPreview();}
function ensureSaveButton(){if(!$('#save-outline')){const b=document.createElement('button');b.id='save-outline';b.className='saved-action';b.textContent='保存修改';b.addEventListener('click',()=>{if(previewTab==='outline')storedOutline=$('#document-preview').innerHTML;saveCurrent();toast('修改已保存在当前浏览器');});$('.preview-shell').append(b);}}
document.addEventListener('click',e=>{const tool=e.target.closest('[data-tool]');if(tool){const key=tool.dataset.tool;if(tool.closest('.header nav')){location.assign(key==='history'?'/workspace.html#recent':'/workspace.html#'+(['rewrite','reduce','aigc','check','ppt','research','format'].includes(key)?'category/':'tool/')+key);return;}openTool(key);return;}const unavailable=e.target.closest('[data-unavailable]');if(unavailable){toast(unavailable.dataset.unavailable);return;}const audience=e.target.closest('[data-audience]');if(audience){degree=audience.dataset.audience;document.querySelectorAll('[data-degree]').forEach(b=>b.classList.toggle('selected',b.dataset.degree===degree));$('#writing').scrollIntoView();$('#paper-title').focus({preventScroll:true});toast('已选择'+degree);return;}const use=e.target.closest('[data-use-topic]');if(use){$('#paper-title').value=use.dataset.useTopic;$('#paper-title').dispatchEvent(new Event('input'));closeDialog();$('#writing').scrollIntoView();return;}const load=e.target.closest('[data-load]');if(load){const d=readStore('paperknow-drafts',[]).find(d=>d.id===Number(load.dataset.load));if(d)restoreDraft(d);return;}const del=e.target.closest('[data-delete]');if(del){writeStore('paperknow-drafts',readStore('paperknow-drafts',[]).filter(d=>d.id!==Number(del.dataset.delete)));renderHistory();toast('已删除这份本地草稿');}});
$('#writing-form').addEventListener('submit',e=>{e.preventDefault();const title=$('#paper-title').value.trim();if(title.length<4){$('#paper-title').setCustomValidity('请至少输入 4 个字符');$('#paper-title').reportValidity();return;}const b=$('#generate-button');b.disabled=true;b.textContent='正在搭建论文框架…';setTimeout(()=>{currentTitle=title;currentDraftId=null;generated=true;storedOutline='';previewTab='outline';document.querySelectorAll('[data-preview]').forEach(x=>{x.classList.toggle('selected',x.dataset.preview==='outline');x.setAttribute('aria-selected',x.dataset.preview==='outline'?'true':'false');});renderPreview();storedOutline=$('#document-preview').innerHTML;saveCurrent();$('#preview-label').textContent='我的论文大纲 · 点击编辑';ensureSaveButton();b.disabled=false;b.innerHTML=svg('sparkles')+'重新生成论文大纲';toast('大纲模板已生成，可直接编辑并导出');if(window.innerWidth<760)$('.result-preview').scrollIntoView({block:'center'});},600);});
$('#paper-title').addEventListener('input',e=>{$('#title-count').textContent=e.target.value.length+'/100';e.target.setCustomValidity('');});
$('#document-preview').addEventListener('paste',e=>{if(!generated)return;e.preventDefault();const text=e.clipboardData.getData('text/plain');const selection=window.getSelection();if(selection.rangeCount){const range=selection.getRangeAt(0);range.deleteContents();const node=document.createTextNode(text);range.insertNode(node);range.setStartAfter(node);range.collapse(true);selection.removeAllRanges();selection.addRange(range);}});
document.querySelectorAll('[data-preview]').forEach(b=>b.addEventListener('click',()=>setPreview(b.dataset.preview)));
$('#export-outline').addEventListener('click',()=>{if(previewTab==='outline'&&generated)storedOutline=$('#document-preview').innerHTML;const el=document.createElement('div');el.innerHTML=storedOutline||outlineHtml();el.querySelectorAll('h3,h4,p').forEach(node=>node.append(document.createTextNode('\n')));download(`${currentTitle}-大纲.txt`,el.textContent);toast('论文大纲已导出');});
$('#quick-start').addEventListener('submit',e=>{e.preventDefault();$('#paper-title').value=e.target.querySelector('input').value;$('#paper-title').dispatchEvent(new Event('input'));$('#writing').scrollIntoView();$('#major').focus({preventScroll:true});});
$('#literature-search').addEventListener('submit',e=>{e.preventDefault();openTool('reading');$('#workspace-text').value=e.target.querySelector('input').value;});
document.querySelectorAll('[data-lit]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-lit]').forEach(x=>x.classList.toggle('selected',x===b));renderLiterature(b.dataset.lit);}));
$('#more-button').addEventListener('click',()=>{const menu=$('#more-menu');menu.hidden=!menu.hidden;$('#more-button').setAttribute('aria-expanded',String(!menu.hidden));});document.addEventListener('click',e=>{if(!e.target.closest('.more-wrap')){$('#more-menu').hidden=true;$('#more-button').setAttribute('aria-expanded','false');}});$('#mobile-menu').addEventListener('click',()=>$('nav').classList.toggle('mobile-open'));document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>$('nav').classList.remove('mobile-open')));$('#close-dialog').addEventListener('click',closeDialog);dialog.addEventListener('close',()=>document.body.style.overflow='');dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
setupDrop($('#main-drop'),$('#paper-file'),$('#file-label'));bindDegree();renderLower();renderPreview();renderLiterature();hydrate();const user=readStore('paperknow-local-profile',null);if(user)$('#account-button').textContent=user.name.slice(0,6);

// Optional browser-agent navigation; unsupported browsers use the normal interface.
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const toolDefinition={name:'paperknow_open_tool',title:'打开 PaperKnow 工具',description:'打开本地体验版中指定工具的工作区；仅导航，不生成内容、不上传文件、不提交检测。',inputSchema:{type:'object',properties:{tool:{type:'string',enum:Object.keys(tools)}},required:['tool'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>k!=='tool')||!Object.hasOwn(tools,input.tool))throw new Error('未知的工具名称');openTool(input.tool);return{opened:input.tool,title:tools[input.tool].name,mode:'local-demo'};}};
 try{Promise.resolve(document.modelContext.registerTool(toolDefinition,{signal:lifecycle.signal})).catch(()=>{});}catch{}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}

// Continue existing local modules from the research dashboard.
const workspaceParams=new URLSearchParams(location.search);
const workspaceDraft=readStore('paperknow-drafts',[]).find(d=>String(d.id)===workspaceParams.get('draft'));
if(workspaceDraft)restoreDraft(workspaceDraft);
else{const requestedTool=workspaceParams.get('tool');if(requestedTool&&(Object.hasOwn(tools,requestedTool)||requestedTool==='writing'))openTool(requestedTool);}
